riffql.200:
query BoardPage200(
    $organization_id: Organization.organization_id,
    $project_id: Project.project_id,
    $status: TicketStatus,
) {
    many tickets from Ticket
        where organization_id == $organization_id
            && project_id == $project_id
            && status == $status
        order by ticket_id asc
        take 200

    return Found {
        tickets: tickets {
            ticket_id
            project_id
            title
            status
            reporter_id
            assignee_id
        }
    }

    outcomes Found
}

